using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Providers.Fake;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace MiniFramework.Assets.Tests
{
    public sealed class AssetsServiceTests
    {
        private static ResourceKey Key(string address="icon",string version="v1")=>new ResourceKey("fake","main",version,address,typeof(string));
        private static CleanupContext Cleanup=>new CleanupContext(CancellationToken.None,Timeout.InfiniteTimeSpan);
        private static FrameworkError Failed=>new FrameworkError(ErrorKind.Provider,"test.failed");
        private sealed class Context:IScopedModuleContext,IServiceResolver
        {
            public IScope Scope {get;}=new Scope("service");public IServiceResolver Services=>this;public CancellationToken LifetimeCancellation=>Scope.LifetimeCancellation;public ICleanupRegistry Cleanup=>Scope.Cleanup;
            public bool TryGet<T>(out T value)where T:class{value=null;return false;}
        }
        private sealed class Env
        {
            internal FakeResourceProvider Provider=new FakeResourceProvider();internal AssetsService Service;internal Context Context=new Context();
            internal static async UniTask<Env> Create(){var e=new Env();e.Service=new AssetsService(e.Provider,"main","v1",Cleanup);Assert.IsTrue((await e.Service.InitializeAsync(e.Context,OperationContext.Unlimited())).IsSuccess);return e;}
            internal async UniTask Finish(){Assert.IsTrue((await Context.Scope.CloseAsync(Cleanup)).IsFullyDrained);Assert.AreEqual(0,Service.RetainedEntryCount);Assert.AreEqual(0,Service.RetainedRequestCount);}
            internal void CompleteRelease(int index=0){Provider.AssetAt<string>(index).Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));}
        }
        [UnityTest] public IEnumerator ColdRequestsDoNotStartProviderAndCloseCleanly()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var owner=new Scope("cold");e.Service.Load<string>(Key(),owner);Assert.AreEqual(0,e.Provider.AssetStartCount);await owner.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator NotReadyWrongVersionAndClosedOwnerRejectBeforeWork()=>UniTask.ToCoroutine(async()=>{var p=new FakeResourceProvider();var s=new AssetsService(p,"main","v1",Cleanup);var owner=new Scope("o");Assert.AreEqual(ErrorKind.NotReady,s.Load<string>(Key(),owner).Error.Kind);var c=new Context();await s.InitializeAsync(c,OperationContext.Unlimited());Assert.AreEqual(ErrorKind.InvalidArgument,s.Load<string>(Key(version:"v2"),owner).Error.Kind);await owner.CloseAsync(Cleanup);Assert.IsFalse(s.Load<string>(Key(),owner).IsSuccess);Assert.AreEqual(0,p.AssetStartCount);await c.Scope.CloseAsync(Cleanup);});
        [UnityTest] public IEnumerator TwentyWaitersShareOneActualLoadAndIndependentLeases()=>UniTask.ToCoroutine(async()=>
        {
            var e=await Env.Create();var owners=new List<Scope>();var waits=new List<UniTask<Result<IAssetLease<string>>>>();
            for(var i=0;i<20;i++){var o=new Scope("o"+i);owners.Add(o);waits.Add(e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited()));}
            Assert.AreEqual(1,e.Provider.AssetStartCount);Assert.AreEqual(1,e.Service.ActualLoadingCount);e.Provider.AssetAt<string>(0).Succeed("shared");
            var leases=new List<IAssetLease<string>>();foreach(var wait in waits){var result=await wait;Assert.IsTrue(result.IsSuccess);leases.Add(result.Value);}
            var ids=new HashSet<string>();foreach(var lease in leases){ids.Add(lease.Id);Assert.AreEqual("shared",lease.Value);}Assert.AreEqual(20,ids.Count);
            for(var i=0;i<19;i++){Assert.IsTrue((await leases[i].ReleaseAsync(Cleanup)).IsSuccess);Assert.IsNull(e.Provider.AssetAt<string>(0).Asset.ReleaseAttempt);}
            var last=leases[19].ReleaseAsync(Cleanup);Assert.AreEqual(1,e.Service.RetainedEntryCount);e.CompleteRelease();Assert.IsTrue((await last).IsSuccess);
            foreach(var o in owners)await o.CloseAsync(Cleanup);await e.Finish();
        });
        [UnityTest] public IEnumerator OneCanceledWaiterDoesNotCancelOthers()=>UniTask.ToCoroutine(async()=>
        {var e=await Env.Create();var a=new Scope("a");var b=new Scope("b");var cts=new CancellationTokenSource();var wa=e.Service.Load<string>(Key(),a).Value.WaitAsync(OperationContext.Unlimited(cts.Token));var wb=e.Service.Load<string>(Key(),b).Value.WaitAsync(OperationContext.Unlimited());cts.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await wa).Error.Kind);Assert.AreEqual(1,e.Service.ActualLoadingCount);e.Provider.AssetAt<string>(0).Succeed("b");var lease=(await wb).Value;Assert.AreEqual("b",lease.Value);await a.CloseAsync(Cleanup);var close=b.CloseAsync(Cleanup);e.CompleteRelease();await close;cts.Dispose();await e.Finish();});
        [UnityTest] public IEnumerator AllCanceledStillOwnActualLoadAndReclaimLatePayload()=>UniTask.ToCoroutine(async()=>
        {var e=await Env.Create();var owner=new Scope("all");var cts=new CancellationTokenSource();var waits=new List<UniTask<Result<IAssetLease<string>>>>();for(var i=0;i<20;i++)waits.Add(e.Service.Load<string>(Key(),owner).Value.WaitAsync(OperationContext.Unlimited(cts.Token)));cts.Cancel();foreach(var w in waits)Assert.AreEqual(ErrorKind.Canceled,(await w).Error.Kind);Assert.AreEqual(1,e.Service.ActualLoadingCount);await owner.CloseAsync(default);e.Provider.AssetAt<string>(0).Succeed("late");Assert.AreEqual(AssetLeaseState.Releasing,e.Provider.AssetAt<string>(0).Asset.State);Assert.AreEqual(1,e.Service.RetainedEntryCount);e.CompleteRelease();Assert.IsTrue((await owner.CloseAsync(Cleanup)).IsFullyDrained);cts.Dispose();await e.Finish();});
        [UnityTest] public IEnumerator ZeroDeadlineAndPreCancellationStartNoLoad()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var cts=new CancellationTokenSource();cts.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Service.Load<string>(Key(),o).Value.WaitAsync(new OperationContext(cts.Token,TimeSpan.Zero))).Error.Kind);Assert.AreEqual(ErrorKind.Timeout,(await e.Service.Load<string>(Key(),o).Value.WaitAsync(default)).Error.Kind);Assert.AreEqual(0,e.Provider.AssetStartCount);await o.CloseAsync(Cleanup);cts.Dispose();await e.Finish();});
        [UnityTest] public IEnumerator TimeoutKeepsBackendOwnershipUntilActualEnd()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(1)));Assert.AreEqual(ErrorKind.Timeout,(await wait).Error.Kind);Assert.AreEqual(1,e.Service.ActualLoadingCount);e.Provider.AssetAt<string>(0).Succeed("late");e.CompleteRelease();await o.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator OwnerCloseBeforeCompletionNeverDeliversLease()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());await o.CloseAsync(default);e.Provider.AssetAt<string>(0).Succeed("late");Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);e.CompleteRelease();await o.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator CancellationWinsWhenPayloadAlreadyCompletedButNotDelivered()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var cts=new CancellationTokenSource();var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited(cts.Token));e.Provider.AssetAt<string>(0).Succeed("ready");cts.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);e.CompleteRelease();await o.CloseAsync(Cleanup);cts.Dispose();await e.Finish();});
        [UnityTest] public IEnumerator WaitMayOnlyBeCalledOnce()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var request=e.Service.Load<string>(Key(),o).Value;var first=request.WaitAsync(OperationContext.Unlimited());Assert.AreEqual(ErrorKind.InvalidState,(await request.WaitAsync(OperationContext.Unlimited())).Error.Kind);e.Provider.AssetAt<string>(0).Succeed("v");await first;var close=o.CloseAsync(Cleanup);e.CompleteRelease();await close;await e.Finish();});
        [UnityTest] public IEnumerator ManualReleaseThenScopeCloseDoesNotReturnTwice()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Succeed("v");var lease=(await wait).Value;var release=lease.ReleaseAsync(Cleanup);var again=lease.ReleaseAsync(Cleanup);var attempt=e.Provider.AssetAt<string>(0).Asset.ReleaseAttempt;e.CompleteRelease();Assert.IsTrue((await release).IsSuccess);Assert.IsTrue((await again).IsSuccess);Assert.AreEqual(ErrorKind.InvalidState,(await lease.ReleaseAsync(Cleanup)).Error.Kind);await o.CloseAsync(Cleanup);Assert.AreSame(attempt,e.Provider.AssetAt<string>(0).Asset.ReleaseAttempt);Assert.Throws<InvalidOperationException>(()=>{var value=lease.Value;});await e.Finish();});
        [UnityTest] public IEnumerator ReleaseWaitTimeoutDoesNotAbandonActualRelease()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Succeed("v");var lease=(await wait).Value;Assert.AreEqual(ErrorKind.Timeout,(await lease.ReleaseAsync(default)).Error.Kind);Assert.AreEqual(AssetLeaseState.Releasing,lease.State);Assert.AreEqual(1,e.Service.RetainedEntryCount);e.CompleteRelease();await o.CloseAsync(Cleanup);Assert.AreEqual(AssetLeaseState.Released,lease.State);await e.Finish();});
        [UnityTest] public IEnumerator FailedReleaseNeedsExplicitLeaseRetry()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Succeed("v");var lease=(await wait).Value;var release=lease.ReleaseAsync(Cleanup);e.Provider.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Failure(Failed));Assert.IsFalse((await release).IsSuccess);Assert.AreEqual(AssetLeaseState.ReleaseFailed,lease.State);Assert.IsFalse((await lease.ReleaseAsync(Cleanup)).IsSuccess);var retry=lease.RetryReleaseAsync(Cleanup);e.CompleteRelease();Assert.IsTrue((await retry).IsSuccess);await o.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator OrphanReleaseFailureIsRetainedForScopeTicketRetry()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var cts=new CancellationTokenSource();var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited(cts.Token));cts.Cancel();await wait;e.Provider.AssetAt<string>(0).Succeed("late");e.Provider.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Failure(Failed));Assert.IsFalse((await o.CloseAsync(Cleanup)).IsFullyDrained);Assert.AreEqual(1,e.Service.ReadDiagnostics().FailedCleanup);var retry=o.RetryFailedAsync(Cleanup);e.CompleteRelease();Assert.IsTrue((await retry).IsFullyDrained);cts.Dispose();await e.Finish();});
        [UnityTest] public IEnumerator NewRequestCannotReuseReleasingHandle()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Succeed("v");var lease=(await wait).Value;var release=lease.ReleaseAsync(Cleanup);Assert.AreEqual(ErrorKind.Unavailable,(await e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited())).Error.Kind);Assert.AreEqual(1,e.Provider.AssetStartCount);e.CompleteRelease();await release;var next=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());Assert.AreEqual(2,e.Provider.AssetStartCount);e.Provider.AssetAt<string>(1).Succeed("new");await next;var close=o.CloseAsync(Cleanup);e.CompleteRelease(1);await close;await e.Finish();});
        [UnityTest] public IEnumerator LoadFailureLeavesNoEntryAndNextRequestCanRetry()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var first=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Fail(Failed);Assert.IsFalse((await first).IsSuccess);Assert.AreEqual(0,e.Service.RetainedEntryCount);var second=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(1).Succeed("ok");await second;var close=o.CloseAsync(Cleanup);e.CompleteRelease(1);await close;await e.Finish();});
        [UnityTest] public IEnumerator DifferentKeysAndServicesDoNotShare()=>UniTask.ToCoroutine(async()=>{var a=await Env.Create();var b=await Env.Create();var o=new Scope("o");var wa=a.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());var wb=b.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());var other=a.Service.Load<string>(Key("other"),o).Value.WaitAsync(OperationContext.Unlimited());Assert.AreEqual(2,a.Provider.AssetStartCount);Assert.AreEqual(1,b.Provider.AssetStartCount);a.Provider.AssetAt<string>(0).Succeed("a");a.Provider.AssetAt<string>(1).Succeed("other");b.Provider.AssetAt<string>(0).Succeed("b");var la=(await wa).Value;var lb=(await wb).Value;var lo=(await other).Value;var ra=la.ReleaseAsync(Cleanup);var rb=lb.ReleaseAsync(Cleanup);var ro=lo.ReleaseAsync(Cleanup);a.CompleteRelease();a.CompleteRelease(1);b.CompleteRelease();await ra;await rb;await ro;await o.CloseAsync(Cleanup);await a.Finish();await b.Finish();});
        private sealed class ThrowingProvider:IAssetProvider
        {public string Id=>"fake";public Result<IProviderOperation<IProviderAsset<T>>> BeginLoad<T>(ResourceKey key)where T:class=>throw new Exception("injected");}
        [UnityTest] public IEnumerator ProviderThrowBecomesFailureAndClearsLedger()=>UniTask.ToCoroutine(async()=>{var s=new AssetsService(new ThrowingProvider(),"main","v1",Cleanup);var c=new Context();await s.InitializeAsync(c,OperationContext.Unlimited());var o=new Scope("o");Assert.AreEqual(ErrorKind.Provider,(await s.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited())).Error.Kind);Assert.AreEqual(0,s.RetainedEntryCount);await o.CloseAsync(Cleanup);await c.Scope.CloseAsync(Cleanup);});
        [UnityTest] public IEnumerator InvalidSuccessfulPayloadIsRejectedWithoutLease()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Operation.Complete(Result<IProviderAsset<string>>.Success(null));Assert.AreEqual(ErrorKind.Integrity,(await wait).Error.Kind);await o.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator ServiceCloseGatesColdRequestsAndDrainsActualWork()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());var close=e.Service.CloseAsync(Cleanup);Assert.AreEqual(ErrorKind.NotReady,e.Service.Load<string>(Key(),o).Error.Kind);Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);Assert.AreEqual(1,e.Service.ActualLoadingCount);e.Provider.AssetAt<string>(0).Succeed("late");e.CompleteRelease();Assert.IsTrue((await close).IsSuccess);await o.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator ContextRegistryRetryRecoversServiceOwnedOrphan()=>UniTask.ToCoroutine(async()=>{var p=new FakeResourceProvider();var s=new AssetsService(p,"main","v1",Cleanup);var context=new GameContext(new[]{new ModuleRegistration(s.Id,s.Dependencies,()=>s,typeof(IAssetsService))},Cleanup);await context.StartAsync(OperationContext.Unlimited());Assert.IsTrue(context.TryGet<IAssetsService>(out var service));var o=new Scope("external-owner");var wait=service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());var close=context.CloseAsync(OperationContext.Unlimited());await wait;p.AssetAt<string>(0).Succeed("late");p.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Failure(Failed));Assert.IsFalse((await close).IsSuccess);Assert.AreEqual(GameContextState.CleanupFailed,context.State);var retry=context.RetryCleanupAsync(Cleanup,OperationContext.Unlimited());p.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));Assert.IsTrue((await retry).IsSuccess);await o.CloseAsync(Cleanup);Assert.AreEqual(0,s.RetainedEntryCount);});
        private sealed class SynchronousProvider:IAssetProvider
        {
            internal readonly FakeResourceProvider Inner=new FakeResourceProvider();internal Action OnBegin;
            public string Id=>"fake";
            public Result<IProviderOperation<IProviderAsset<T>>> BeginLoad<T>(ResourceKey key)where T:class
            {var operation=Inner.BeginLoad<T>(key);OnBegin?.Invoke();Inner.AssetAt<T>(Inner.AssetStartCount-1).Succeed((T)(object)"sync");return operation;}
        }
        [UnityTest] public IEnumerator SynchronousProviderCompletionDoesNotLoseOwnership()=>UniTask.ToCoroutine(async()=>
        {var p=new SynchronousProvider();var s=new AssetsService(p,"main","v1",Cleanup);var c=new Context();await s.InitializeAsync(c,OperationContext.Unlimited());var o=new Scope("sync");var lease=(await s.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited())).Value;Assert.AreEqual("sync",lease.Value);var close=o.CloseAsync(Cleanup);p.Inner.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));await close;await c.Scope.CloseAsync(Cleanup);Assert.AreEqual(0,s.RetainedEntryCount);Assert.AreEqual(0,s.RetainedRequestCount);});
        [UnityTest] public IEnumerator ProviderReentrantOwnerCloseRetainsLateHandle()=>UniTask.ToCoroutine(async()=>
        {var p=new SynchronousProvider();var s=new AssetsService(p,"main","v1",Cleanup);var c=new Context();await s.InitializeAsync(c,OperationContext.Unlimited());var o=new Scope("reentrant");UniTask<CleanupReport> closing=default;p.OnBegin=()=>closing=o.CloseAsync(default);var result=await s.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());Assert.AreEqual(ErrorKind.Canceled,result.Error.Kind);await closing;Assert.AreEqual(AssetLeaseState.Releasing,p.Inner.AssetAt<string>(0).Asset.State);Assert.AreEqual(1,s.RetainedEntryCount);p.Inner.AssetAt<string>(0).Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));await o.CloseAsync(Cleanup);await c.Scope.CloseAsync(Cleanup);Assert.AreEqual(0,s.RetainedEntryCount);});
        [UnityTest] public IEnumerator NewWaiterCanShareAlreadyLoadedEntry()=>UniTask.ToCoroutine(async()=>
        {var e=await Env.Create();var a=new Scope("a");var b=new Scope("b");var wait=e.Service.Load<string>(Key(),a).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Succeed("cached");var first=(await wait).Value;var second=(await e.Service.Load<string>(Key(),b).Value.WaitAsync(OperationContext.Unlimited())).Value;Assert.AreEqual(1,e.Provider.AssetStartCount);Assert.AreNotEqual(first.Id,second.Id);await first.ReleaseAsync(Cleanup);Assert.AreEqual("cached",second.Value);var close=b.CloseAsync(Cleanup);e.CompleteRelease();await close;await a.CloseAsync(Cleanup);await e.Finish();});
        [UnityTest] public IEnumerator WrongKeyPayloadIsReclaimedInsteadOfDropped()=>UniTask.ToCoroutine(async()=>
        {var foreign=new FakeResourceProvider();foreign.BeginLoad<string>(Key("wrong"));foreign.AssetAt<string>(0).Succeed("wrong");var handle=foreign.AssetAt<string>(0).Asset;var e=await Env.Create();var o=new Scope("o");var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(0).Operation.Complete(Result<IProviderAsset<string>>.Success(handle));Assert.AreEqual(ErrorKind.Integrity,(await wait).Error.Kind);Assert.AreEqual(AssetLeaseState.Releasing,handle.State);handle.ReleaseAttempt.Complete(Result<Unit>.Success(default));await o.CloseAsync(Cleanup);await e.Finish();});
        private sealed class ImmediateOperation<T>:IProviderOperation<T>
        {
            private readonly Result<T> result;public string Id=>"immediate";public BackendState State=>BackendState.Succeeded;
            public UniTask<Result<T>> Completion=>UniTask.FromResult(result);internal ImmediateOperation(T value){result=Result<T>.Success(value);}
        }
        private sealed class ReentrantReleaseProvider:IAssetProvider,IProviderAsset<string>
        {
            internal readonly FakeAsset<string> Asset;internal Action OnRelease;public string Id=>"fake";
            internal ReentrantReleaseProvider(){var p=new FakeResourceProvider();p.BeginLoad<string>(AssetsServiceTests.Key());p.AssetAt<string>(0).Succeed("value");Asset=p.AssetAt<string>(0).Asset;}
            public Result<IProviderOperation<IProviderAsset<T>>> BeginLoad<T>(ResourceKey key)where T:class=>Result<IProviderOperation<IProviderAsset<T>>>.Success(new ImmediateOperation<IProviderAsset<T>>((IProviderAsset<T>)(object)this));
            public ResourceKey Key=>Asset.Key;public AssetLeaseState State=>Asset.State;public string Value=>Asset.Value;
            public Result<IProviderOperation<Unit>> BeginRelease(CleanupContext cleanup){var operation=Asset.BeginRelease(cleanup);OnRelease?.Invoke();Asset.ReleaseAttempt.Complete(Result<Unit>.Failure(Failed));return operation;}
            public Result<IProviderOperation<Unit>> RetryRelease(CleanupContext cleanup)=>Asset.RetryRelease(cleanup);
        }
        [UnityTest] public IEnumerator ReentrantRetryCannotReplaceOriginalReleaseResult()=>UniTask.ToCoroutine(async()=>
        {
            var provider=new ReentrantReleaseProvider();var service=new AssetsService(provider,"main","v1",Cleanup);var context=new Context();await service.InitializeAsync(context,OperationContext.Unlimited());var owner=new Scope("generation");
            var lease=(await service.Load<string>(Key(),owner).Value.WaitAsync(OperationContext.Unlimited())).Value;
            UniTask<Result> retry=default;Result nestedResult=default;UniTask observer=default;
            async UniTask Observe(){nestedResult=await service.CloseAsync(Cleanup);retry=service.RetryCleanupAsync(Cleanup);}
            provider.OnRelease=()=>observer=Observe().Preserve();
            var original=lease.ReleaseAsync(Cleanup);
            Assert.AreNotEqual(UniTaskStatus.Pending,original.Status,"Old release must not join the reentrant retry.");
            Assert.IsFalse((await original).IsSuccess);Assert.IsFalse(nestedResult.IsSuccess);await observer;
            provider.Asset.ReleaseAttempt.Complete(Result<Unit>.Success(default));Assert.IsTrue((await retry).IsSuccess);await owner.CloseAsync(Cleanup);await context.Scope.CloseAsync(Cleanup);
        });
        [UnityTest] public IEnumerator HundredLoadReleaseCyclesReturnLedgerToBaseline()=>UniTask.ToCoroutine(async()=>{var e=await Env.Create();for(var i=0;i<100;i++){var o=new Scope("o"+i);var wait=e.Service.Load<string>(Key(),o).Value.WaitAsync(OperationContext.Unlimited());e.Provider.AssetAt<string>(i).Succeed("v");await wait;var close=o.CloseAsync(Cleanup);e.CompleteRelease(i);await close;Assert.AreEqual(0,e.Service.RetainedEntryCount);Assert.AreEqual(0,e.Service.RetainedRequestCount);}await e.Finish();});
    }
}
